@startuml

class Center {
  + Name : string
  + Address : string
}

class Room {
  + Number : int
  + Capacity : int
}

class Person {
  + FirstName : string
  + FamilyName : string
  + BirthDate : date
}

class Trainer extends Person {
  + Diploma : string
}

class Session {
  + Date : date
  + StartHour : time
}

class GroupSession extends Session {
  + Type : string
}

class IndividualSession extends Session {}

Person "0..*" -- "*" Session : participates in

Trainer "0..1" -- "*" GroupSession : supervises

Center "1" *-- "1..*" Room
Center "1" -- "*" Session
Room "1" -- "*" Session

@enduml

